css:
.card{position:relative; z-index:1}            /* 本体を手前に */
.card .deco{position:absolute; z-index:0;       /* ← 0。前に出さない */
  right:6%; bottom:100%; transform:translateY(38%);
  width:32%; pointer-events:none}

/* CTAの裏から頭だけ覗かせる版 */
.entry{position:relative; z-index:2; width:92px; aspect-ratio:1;
  border-radius:50%; background:#F2258E; color:#fff;
  display:grid; place-content:center}
.peek{position:absolute; z-index:1; left:50%; bottom:78%; translate:-50% 0}
